package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextUniversalFrozenConstraints.*;
import org.kanger.ContextUniversalFrozenConstraints.Result;
import org.kanger.ContextUniversalInputResiduals.Residual;
import org.kanger.ContextWitnessResultTransport.*;

/** Fixed positive applications have one simultaneous step, with a single consistent typed binding. */
public final class ContextUniversalSignedApplicationsRunner {
    static final int WORK=64000000;static int checks;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalNativeRows.Result rows(Snapshot x,Snapshot a){ContextUniversalNativeRows.Result r=ContextUniversalNativeRows.inspect(x,a,64,WORK);require(r.classified&&r.withinShape,r.reason);return r;}
    static Result close(Snapshot x,Snapshot a,Packet common,PrivatePool pool,int depth){Result r=ContextUniversalFrozenConstraints.closeSignedApplications(rows(x,a),common,pool,null,16,depth,512,256,WORK);require(r.closed&&r.signedUnits&&r.applications,r.reason);ContextUniversalFrozenConstraints.check(r,depth,()->{});Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof p:r.proofs)audit(p,seen);return r;}
    static void audit(Proof p,Set<Proof> seen){if(!seen.add(p))return;require(p.exchanged==null,"no symbolic import in this fixture");if(p.original!=null){require(p.original.parts.contains(p.part)&&p.support.depth==0&&p.support.sources.equals(Collections.singleton(p.original.original.source)),"actual whole native root");return;}if(p.input!=null){require(p.input.proofs.contains(p.inputProof)&&p.support.equals(p.inputProof),"actual carried proof grade/source, no reset");return;}Set<Source> sources=new HashSet<>();int depth=0;Residual expected;
        if(p.producer!=null){audit(p.producer,seen);sources.addAll(p.producer.support.sources);depth=p.producer.support.depth;List<Residual> donors=new ArrayList<>();for(Proof donor:p.donors){audit(donor,seen);sources.addAll(donor.support.sources);depth=Math.max(depth,donor.support.depth);donors.add(donor.clause);}expected=ContextUniversalInputResiduals.applyFixedPositiveUnits(p.producer.clause,donors,()->{});require(p.donors.size()>=2&&p.clause.variables.isEmpty()&&p.clause.literals.get(0).positive,"fixed positive application, full immutable donor tuple");}
        else{audit(p.unit,seen);audit(p.horn,seen);sources.addAll(p.unit.support.sources);sources.addAll(p.horn.support.sources);depth=Math.max(p.unit.support.depth,p.horn.support.depth);expected=ContextUniversalInputResiduals.resolveSignedUnit(p.unit.clause,p.horn.clause,p.pivot,()->{});}
        require(p.clause==null?expected==null:expected!=null&&p.clause.equivalent(expected,()->{}),"independent typed inference replay");require(p.support.sources.equals(sources)&&p.support.depth==depth+1,"exact whole parent Sources and one max-parent application step");
    }
    static Proof unit(Result r,String name){return r.proofs.stream().filter(p->p.clause!=null&&p.clause.literals.size()==1&&p.clause.literals.get(0).predicate.equals(name)).findFirst().get();}
    static ConstraintTransfer transfer(Result r,Packet common,PrivatePool pool,int depth){ConstraintTransfer t=pool==null?ContextWitnessResultTransport.transferConstraints(r,common,depth,WORK):ContextWitnessResultTransport.transferConstraintsPrivate(r,pool,depth,WORK);require(t.transferred,t.reason);ContextUniversalSignedProductAudit.Result audit=ContextUniversalSignedProductAudit.bind(r,t,65536,WORK);require(audit.bound,audit.reason);return t;}
    static void baselineAndNative()throws Exception {
        String rule="!@w p(w)&&q(w)->r(w);";Snapshot x=bind(true,"!p(1); !q(1);"),a=bind(false,rule);Packet input=ContextPrivateWitnessPoolRunner.common(x);Result legacy=ContextUniversalFrozenConstraints.closeSigned(rows(x,a),input,null,16,16,512,256,WORK);require(legacy.closed&&!legacy.applications&&unit(legacy,"r").support.depth==2,"legacy binary recipe remains r2");ConstraintTransfer denied=ContextWitnessResultTransport.transferConstraints(legacy,input,1,WORK);require(!denied.transferred&&denied.output==null,"baseline binary fact bound1 refusal");
        Result r=close(x,a,input,null,1);Proof produced=unit(r,"r");require(produced.producer!=null&&produced.support.depth==1&&produced.support.sources.size()==3,"simultaneous r1/exact three Sources");ConstraintTransfer t=transfer(r,input,null,1);
        ContextUniversalFrozenBranch.Result nativeProof=ContextUniversalFrozenBranch.run(x,a,input,new ContextUniversalFrozenBranch.Limits(16,16,1,512,256,WORK,500000,65536));require(nativeProof.produced,nativeProof.phase+" "+nativeProof.reason);require(ContextWitnessResultTransport.sameContents(t.output,nativeProof.products.transfer.output,WORK),"actual native pipeline and signed application have identical fixed Source minima");require(nativeProof.products.transfer.proof.conclusions.stream().anyMatch(c->c.fact.literals.get(0).predicate.equals("r")&&c.support.equals(produced.support)),"same exact actual observed native event grade/source");
        try{produced.donors.clear();throw new AssertionError("mutable donors");}catch(UnsupportedOperationException expected){++checks;}
        Snapshot negative=bind(false,"!~unused(1);");Snapshot full=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,negative),WORK);Result mixed=close(x,full,input,null,16);require(mixed.input.rows.size()==4&&mixed.proofs.stream().anyMatch(p->p.original!=null&&p.original.original.source.equals(negative.primary.get(0).source)),"full signed ledger retained, no producer-only Snapshot");require(unit(mixed,"r").support.equals(produced.support),"unrelated negative root cannot inflate positive application Source");transfer(mixed,input,null,1);
        ConstraintTransfer zero=ContextWitnessResultTransport.transferConstraints(r,input,0,WORK);require(!zero.transferred&&zero.output==null&&zero.local==null,"fact bound0 has no output prefix");
        Result bounded=ContextUniversalFrozenConstraints.closeSignedApplications(rows(x,a),input,null,null,1,16,512,256,WORK);require(!bounded.closed&&bounded.proofs.isEmpty()&&bounded.emptyProofs.isEmpty(),"round cap hides partial application state");bounded=ContextUniversalFrozenConstraints.closeSignedApplications(rows(x,a),input,null,null,16,16,512,256,1);require(!bounded.closed&&bounded.proofs.isEmpty(),"work cap no partial proof prefix");
    }
    static void originsAndReuse()throws Exception {
        String seed="!$w p(w,1)&&q(w,1);",rule="!@w p(w,1)&&q(w,1)->out(w,1);";Snapshot x=bind(true,seed),a=bind(false,rule);Packet common=ContextPrivateWitnessPoolRunner.common(x);Result r=close(x,a,common,null,1);Proof out=unit(r,"out");require(out.producer!=null&&out.support.depth==1&&out.support.sources.size()==2&&out.clause.origins.size()==1,"co-bound private parameter remains rigid, bundle Source counted once");ConstraintTransfer t=transfer(r,common,null,1);ContextUniversalFrozenBranch.Result nativeProof=ContextUniversalFrozenBranch.run(x,a,common,new ContextUniversalFrozenBranch.Limits(16,16,1,512,256,WORK,500000,65536));require(nativeProof.produced&&ContextWitnessResultTransport.sameContents(t.output,nativeProof.products.transfer.output,WORK),"actual native Origin products agree exactly");
        Snapshot split=bind(true,"!$w p(w,1); !$w q(w,1);");Result independent=close(split,a,ContextPrivateWitnessPoolRunner.common(split),null,16);require(independent.proofs.stream().noneMatch(p->p.clause!=null&&p.clause.literals.size()==1&&p.clause.literals.get(0).predicate.equals("out")),"different Origins cannot satisfy one repeated binding");
        Snapshot owner=bind(true,"!anchor(1); "+rule),privateSeed=bind(false,seed);Packet base=ContextPrivateWitnessPoolRunner.common(owner);PrivatePool pool=ContextWitnessResultTransport.privatePool(base,owner,privateSeed,WORK);ConstraintTransfer shared=transfer(close(owner,privateSeed,base,pool,1),base,pool,1);require(shared.output.items.stream().anyMatch(i->i.atom.predicate.equals("out")&&i.atom.arguments.get(0).origin!=null)&&shared.output.items.stream().noneMatch(i->i.atom.predicate.equals("p")||i.atom.predicate.equals("q")),"actual private multi-premise bindings share derived result, not raw donor bundle");
        Snapshot same=bind(true,"!p(7,1);"),repeat=bind(false,"!@u @v p(u,1)&&p(v,1)->pair(u,v);");Result reused=close(same,repeat,ContextPrivateWitnessPoolRunner.common(same),null,1);Proof pair=unit(reused,"pair");require(pair.producer!=null&&pair.donors.size()==2&&pair.donors.get(0)==pair.donors.get(1)&&pair.support.sources.size()==2,"one actual donor may satisfy two coincident formal premises");
        Snapshot crossed=bind(true,"!p(1,2); !q(2,1);"),bad=bind(false,"!@u @v p(u,v)&&q(u,v)->out(u,v);"),good=bind(false,"!@u @v p(u,v)&&q(v,u)->out(u,v);");Packet cp=ContextPrivateWitnessPoolRunner.common(crossed);Result failed=close(crossed,bad,cp,null,16);require(failed.proofs.stream().noneMatch(p->p.clause!=null&&p.clause.literals.size()==1&&p.clause.literals.get(0).predicate.equals("out")),"one consistent tuple substitution across every premise");require(unit(close(crossed,good,cp,null,1),"out").support.depth==1,"shared two-variable substitution handles crossed arguments");
    }
    static void alternativesHistoricalAndScope()throws Exception {
        Snapshot x=bind(true,"!p(1); !q(1);"),a=bind(false,"!@w p(w)&&q(w)->r(w);"),loop=bind(false,"!@w r(w)->r(w);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,loop),WORK);Packet common=ContextPrivateWitnessPoolRunner.common(x);Result r=close(x,group,common,null,16);ConstraintTransfer t=transfer(r,common,null,2);Item item=t.output.items.stream().filter(i->i.atom.predicate.equals("r")).findFirst().get();require(item.proofs.size()==2&&item.proofs.stream().anyMatch(p->p.depth==1&&p.sources.size()==3)&&item.proofs.stream().anyMatch(p->p.depth==2&&p.sources.size()==4),"all Source alternatives and deeper supersets keep their own actual minima");require(!ContextWitnessResultTransport.transferConstraints(r,common,1,WORK).transferred,"shorter different-Source product cannot cover deeper alternative");Snapshot reverse=ContextProductionNativeBinding.trusted("own",Arrays.asList(loop,a),WORK);require(ContextWitnessResultTransport.sameContents(t.output,transfer(close(x,reverse,common,null,16),common,null,2).output,WORK),"trusted member order preserves complete minima");
        Snapshot sx=bind(true,"!seed(1); !q(1);"),pa=bind(false,"!@w seed(w)->p(w);"),pb=bind(false,"!@w p(w)&&q(w)->r(w);");Packet initial=ContextPrivateWitnessPoolRunner.common(sx);Result first=close(sx,pa,initial,null,16);Packet carried=transfer(first,initial,null,1).output;Result later=close(sx,pb,carried,null,16);Proof out=unit(later,"r");require(out.producer!=null&&out.support.depth==2&&out.support.sources.size()==4&&out.donors.stream().anyMatch(p->p.input!=null&&p.support.depth==1),"historical actual donor grade1 makes application2, no reset to0");transfer(later,carried,null,2);
        Snapshot symbolic=bind(true,"!anchor(1); !@w p(w,1); !@w q(w,1);"),consumer=bind(false,"!@w p(w,1)&&q(w,1)->r(w,1);");Packet sp=ContextPrivateWitnessPoolRunner.common(symbolic);Result open=close(symbolic,consumer,sp,null,16);Proof symbolicResult=unit(open,"r");require(symbolicResult.producer==null&&!symbolicResult.clause.variables.isEmpty()&&symbolicResult.support.depth==2,"symbolic premises stay binary; no finite instantiation or unproved one-step grade");
        Snapshot negative=bind(false,"!@w p(w)&&q(w)->~r(w);");Proof notR=unit(close(x,negative,common,null,16),"r");require(notR.producer==null&&!notR.clause.literals.get(0).positive&&notR.support.depth==2,"negative conclusion hyperapplication remains explicitly outside this mode");
        Snapshot nr=bind(false,"!~r(1);");Snapshot conflict=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,nr),WORK);Result refuted=close(x,conflict,common,null,16);require(refuted.xRefuted&&refuted.emptyProofs.stream().anyMatch(p->p.support.depth==2&&p.support.sources.size()==4),"positive application plus signed negative root gives actual empty2");List<Proof> evidence=ContextUniversalFrozenConstraints.rejectionEvidence(refuted,WORK);Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof p:evidence)audit(p,seen);require(evidence.stream().allMatch(p->p.clause==null),"flattened rejection preserves application DAGs and grade");require(!ContextWitnessResultTransport.transferConstraints(refuted,common,16,WORK).transferred,"refuted application frame cannot export any products");
    }
    static void widthAndImportedEvidence()throws Exception {
        Snapshot x=bind(true,"!p(1); !q(1); !t(1);"),a=bind(false,"!@w p(w)&&q(w)&&t(w)->r(w);");Packet cp=ContextPrivateWitnessPoolRunner.common(x);Result r=close(x,a,cp,null,16);Proof wide=unit(r,"r");require(wide.producer!=null&&wide.donors.size()==3&&wide.support.depth==1&&wide.support.sources.size()==4,"three actual premises still one application step");transfer(r,cp,null,1);
        Snapshot owner=bind(true,"!p(1,1); !q(1,1); !@v top(v,1);"),producer=bind(false,"!@w p(w,1)&&q(w,1)->r(w,1); !@w @v r(w,1)&&top(v,1)->s(w,v);");Packet common=ContextPrivateWitnessPoolRunner.common(owner);Map<Cut,Result> donors=new LinkedHashMap<>();donors.put(Cut.of(owner),close(owner,null,common,null,16));donors.put(Cut.of(producer),close(owner,producer,common,null,16));
        ContextUniversalSignedUnitExchange.Collection collected=ContextUniversalSignedUnitExchange.collect(owner,common,new ArrayList<>(donors.keySet()),donors,512,256,16,WORK);require(collected.collected,collected.reason);require(collected.output.units.stream().anyMatch(u->u.clause.literals.get(0).predicate.equals("s")&&u.support.depth==2&&u.owner.applications),"application proof can underlie later symbolic unit without resetting grade");
        Snapshot negative=bind(false,"!@w @v ~s(w,v);");Result imported=ContextUniversalFrozenConstraints.closeSignedUnits(rows(owner,negative),common,null,collected.output,16,16,512,256,WORK);require(imported.closed&&imported.xRefuted&&!imported.applications,imported.reason);ContextUniversalFrozenConstraints.check(imported,16,()->{});require(imported.emptyProofs.stream().anyMatch(p->p.support.depth==3&&p.support.sources.size()==6),"old binary consumer verifies historical application owner and exact empty3/six Sources");
        List<Proof> evidence=ContextUniversalFrozenConstraints.rejectionEvidence(imported,WORK);Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof proof:evidence)audit(proof,seen);require(seen.stream().anyMatch(p->p.producer!=null)&&seen.stream().noneMatch(p->p.exchanged!=null),"flattened rejection keeps checked hyperapplication, drops historical Exchange owner");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("signed-applications-").toString());baselineAndNative();originsAndReuse();alternativesHistoricalAndScope();widthAndImportedEvidence();System.out.println("CONTEXT_UNIVERSAL_SIGNED_APPLICATIONS_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
